// Generated by OrchestKit Claude Plugin
// Created: 2026-09-13

/**
 * core-bare-flip: detect core.bare=true in a working checkout (#4070).
 *
 * Every fixture is a throwaway repository under the OS temp dir, built with
 * the caller's GIT_* locators stripped so a run inside a git hook can never
 * reach the real repository (the exact leak #4070 is about).
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, realpathSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { coreBareFlipWarning, findCoreBareFlip } from '../../lib/core-bare-flip.js';

let tmp: string;

function isolatedGitEnv(): NodeJS.ProcessEnv {
  const {
    GIT_DIR,
    GIT_WORK_TREE,
    GIT_INDEX_FILE,
    GIT_PREFIX,
    GIT_COMMON_DIR,
    GIT_OBJECT_DIRECTORY,
    ...env
  } = process.env;
  return { ...env, HOME: tmp, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_SYSTEM: '/dev/null' };
}

function git(cwd: string, ...args: string[]): string {
  return execFileSync('git', args, { cwd, env: isolatedGitEnv(), encoding: 'utf8', stdio: 'pipe' }).trim();
}

/** A primary checkout with one commit, plus a linked worktree at .worktrees/wt. */
function repoWithWorktree(): { main: string; wt: string } {
  const main = join(tmp, 'main');
  mkdirSync(main);
  git(main, 'init', '-q');
  git(main, '-c', 'user.email=t@t', '-c', 'user.name=t', '-c', 'commit.gpgsign=false',
    'commit', '-q', '--allow-empty', '-m', 'init');
  const wt = join(main, '.worktrees', 'wt');
  git(main, 'worktree', 'add', '-q', wt, '-b', 'wt');
  return { main, wt };
}

function flip(main: string): void {
  git(tmp, 'config', '--file', join(main, '.git', 'config'), 'core.bare', 'true');
}

beforeEach(() => {
  tmp = realpathSync(mkdtempSync(join(tmpdir(), 'core-bare-flip-')));
});

afterEach(() => {
  rmSync(tmp, { recursive: true, force: true });
});

describe('findCoreBareFlip', () => {
  it('returns null for a healthy checkout', () => {
    const { main, wt } = repoWithWorktree();
    expect(findCoreBareFlip(main)).toBeNull();
    expect(findCoreBareFlip(wt)).toBeNull();
  });

  it('detects the flip from the primary checkout', () => {
    const { main } = repoWithWorktree();
    flip(main);
    expect(findCoreBareFlip(main)).toEqual({ checkout: main, config: join(main, '.git', 'config') });
  });

  it('detects the shared flip from a linked worktree and names the main config', () => {
    const { main, wt } = repoWithWorktree();
    flip(main);
    expect(findCoreBareFlip(wt)).toEqual({ checkout: wt, config: join(main, '.git', 'config') });
  });

  it('walks up from a subdirectory of the checkout', () => {
    const { main } = repoWithWorktree();
    const sub = join(main, 'a', 'b');
    mkdirSync(sub, { recursive: true });
    flip(main);
    expect(findCoreBareFlip(sub)?.config).toBe(join(main, '.git', 'config'));
  });

  it('reads git boolean spellings and ignores core subsections', () => {
    const { main } = repoWithWorktree();
    const config = join(main, '.git', 'config');
    git(tmp, 'config', '--file', config, 'core.bare', 'yes');
    expect(findCoreBareFlip(main)).not.toBeNull();
    git(tmp, 'config', '--file', config, 'core.bare', 'false');
    git(tmp, 'config', '--file', config, 'core.x.bare', 'true');
    expect(findCoreBareFlip(main)).toBeNull();
  });

  it('ignores a genuine bare repository and a directory outside any repo', () => {
    const bare = join(tmp, 'origin.git');
    git(tmp, 'init', '-q', '--bare', bare);
    expect(findCoreBareFlip(bare)).toBeNull();
    const plain = join(tmp, 'plain');
    mkdirSync(plain);
    expect(findCoreBareFlip(plain)).toBeNull();
  });

  it('prints a fix command that actually repairs the primary checkout', () => {
    const { main, wt } = repoWithWorktree();
    flip(main);
    // Measured on git 2.54: the primary checkout breaks, a linked worktree
    // still resolves. The warning must hold from either place.
    expect(() => git(main, 'rev-parse', '--show-toplevel')).toThrow(/must be run in a work tree/);

    const found = findCoreBareFlip(wt);
    expect(found).not.toBeNull();
    const warning = coreBareFlipWarning(found!);
    expect(warning).toContain(main);
    const fix = warning.match(/Fix: (git config --file \S+ core\.bare false)/);
    expect(fix).not.toBeNull();
    const [, ...args] = fix![1].split(' ');
    git(tmp, ...args);

    expect(git(main, 'rev-parse', '--show-toplevel')).toBe(main);
    expect(findCoreBareFlip(wt)).toBeNull();
  });
});
